contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call the fallback by sending a plain call with value `amount`.
    // Parameters: amount to send, and a guess of current block.timestamp to allow reasoning.
    function run(uint amount, uint /*unused_timestamp_guess*/) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= amount);

        // observe before-state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        // invoke fallback by calling without function selector
        try c.call{value: amount}("") returns (bytes memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint ourBal = address(this).balance;

        // General rule:
        // If the call did not revert then pastBlockTime must have strictly increased
        // (since fallback requires block.timestamp > pastBlockTime), and the contract
        // balance is either unchanged or zero. If it became zero then it must be
        // because block.number % 15 == 0 (the fallback sends full balance to msg.sender).
        // We cannot read block.number here, so we assert the implication form:
        // not reverted => (afterPast > beforePast && (afterBal == beforeBal || afterBal == 0))
        // and if afterBal == 0 then reverted must be false (i.e., a successful drain).
        assert(
            reverted || (
                afterPast > beforePast
                && (afterBal == beforeBal || afterBal == 0)
                && (afterBal != 0 || !reverted)
            )
        );
    }

    // allow receiving ETH when the tested contract transfers to us
    receive() external payable {}
}

