        // Note: fallback requires msg.value == 10 ether and block.timestamp > pastBlockTime.

        if (reverted) {
            // if reverted, no observable changes to c or this
            assert(afterPast == beforePast && afterBalC == beforeBalC && afterBalThis == beforeBalThis);
        } else {
            // call succeeded
            // must have sent exactly 10 ether
            // Ensure that because call succeeded, amount was 10 ether and block.timestamp > beforePast
            bool sentTen = (amount == 10 ether);
            bool timeIncreased = (afterPast == block.timestamp && block.timestamp > beforePast);

