            if (block.number % 15 == 0) {
                // after call, contract balance should be zero and this contract's balance increased by previous c balance
                assert(sentTen && timeIncreased && afterBalC == 0 && afterBalThis == beforeBalThis + beforeBalC);
            } else {
                // otherwise, contract keeps funds: its balance increases by amount and this contract balance decreases by amount
                assert(sentTen && timeIncreased && afterBalC == beforeBalC + amount && afterBalThis == beforeBalThis - amount);
            }
        }
    }

    // allow receiving Ether when C transfers out to this contract
    receive() external payable {}
}

